def compute_model_placement(gpu_num, models):
    """Randomized multi-start greedy + local search (move/swap) minimizing
    max KVPR. Starts from several greedy seeds, then repeatedly moves or
    swaps models out of the bottleneck GPU to reduce the maximum KVPR."""
    import random

    if not models:
        return {g: [] for g in range(gpu_num)}

    def score(assign):
        load = [0.0] * gpu_num
        mem = [0.0] * gpu_num
        for m, g in assign:
            load[g] += m.req_rate / m.slo
            mem[g] += m.model_size
        return max(load[g] / (GPU_MEM_SIZE - mem[g]) for g in range(gpu_num))

    def feasible(assign):
        mem = [0.0] * gpu_num
        for m, g in assign:
            mem[g] += m.model_size
            if mem[g] > GPU_MEM_SIZE:
                return False
        return True

    def greedy(order, eps):
        assign = []
        mem = [0.0] * gpu_num
        load = [0.0] * gpu_num
        for m in order:
            cands = [g for g in range(gpu_num) if mem[g] + m.model_size <= GPU_MEM_SIZE]
            if not cands:
                return None
            if random.random() < eps:
                g = random.choice(cands)
            else:
                g = min(cands, key=lambda g: load[g] / (GPU_MEM_SIZE - mem[g] - m.model_size))
            assign.append((m, g))
            mem[g] += m.model_size
            load[g] += m.req_rate / m.slo
        return assign

    best, best_s = None, float("inf")
    random.seed(42)
    seeds = [
        sorted(models, key=lambda x: x.req_rate / x.slo, reverse=True),
        sorted(models, key=lambda x: x.model_size, reverse=True),
    ]
    tries = 0
    while tries < 300:
        order = seeds[tries % 2] if tries < 4 else sorted(models, key=lambda x: random.random())
        assign = greedy(order, eps=0.15)
        tries += 1
        if assign is None:
            continue
        # local search: move/swap from bottleneck GPU
        for _ in range(200):
            cur = score(assign)
            improved = False
            loads = {}
            mems = {}
            for m, g in assign:
                loads[g] = loads.get(g, 0) + m.req_rate / m.slo
                mems[g] = mems.get(g, 0) + m.model_size
            bg = max(range(gpu_num), key=lambda g: loads[g] / (GPU_MEM_SIZE - mems[g]))
            for i, (m, g) in enumerate(assign):
                if g != bg:
                    continue
                for h in range(gpu_num):
                    if h == g or mems[h] + m.model_size > GPU_MEM_SIZE:
                        continue
                    assign[i] = (m, h)
